parameters.jsCode:
// Establish what is true about the two screenshots before any model sees them,
// and assemble the vision request.
//
// The point of this node is guard rail 1. A vision model asked "what changed?"
// will always find something - show it the same image twice and it will write a
// confident paragraph about spacing and shade. Whether two files are identical
// is not a judgement call, so it is settled here in code and the model is not
// asked at all.
//
// There is no image library in a Code node, so there is no pixel diff to be had.
// What can be read straight from the bytes is: are they identical, how big is
// each canvas, what format, and how much did the file size move. Those are
// stated as fact; everything else is the model's job.

const hook = $('Visual Diff Webhook').first().json;
const body = (hook && hook.body) || hook || {};

let binary = {};
try { binary = $input.first().binary || {}; } catch (e) { binary = {}; }

const CONTEXT = String(body.context || '').trim();
const ISSUE_KEY = String(body.issue_key || '').trim();

// --- getting the two images -------------------------------------------------
// Buffers give the full set of facts. URLs are passed straight to the model,
// which is cheaper than fetching them - but it costs the identical-images
// check, and that trade is reported rather than hidden.
function grab(role, altRole) {
  const key = Object.keys(binary).find((k) => k.toLowerCase() === role || k.toLowerCase() === altRole);
  if (key && binary[key] && binary[key].data) {
    return { kind: 'buffer', buf: Buffer.from(binary[key].data, 'base64'), mime: binary[key].mimeType || 'image/png' };
  }
  const b64 = body[role + '_base64'] || body[role + 'Base64'];
  if (typeof b64 === 'string' && b64.length > 32) {
    const clean = b64.replace(/^data:[^;]+;base64,/, '');
    return { kind: 'buffer', buf: Buffer.from(clean, 'base64'), mime: 'image/png' };
  }
  const url = body[role + '_url'] || body[role + 'Url'];
  if (typeof url === 'string' && /^https?:\/\//.test(url)) return { kind: 'url', url };
  return null;
}

const before = grab('before', 'before_image');
const after = grab('after', 'after_image');

if (!before || !after) {
  throw new Error('Two images are required. Send them as binary fields named "before" and "after", ' +
    'as before_base64 / after_base64, or as before_url / after_url.');
}

// --- reading dimensions out of the file header ------------------------------
function dimensions(buf) {
  if (!buf || buf.length < 24) return null;
  // PNG: 8 byte signature, then the IHDR chunk carries width and height.
  if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) {
    return { format: 'png', width: buf.readUInt32BE(16), height: buf.readUInt32BE(20) };
  }
  // JPEG: walk the markers to the first start-of-frame, which holds the size.
  if (buf[0] === 0xff && buf[1] === 0xd8) {
    let i = 2;
    while (i < buf.length - 9) {
      if (buf[i] !== 0xff) { i++; continue; }
      const marker = buf[i + 1];
      // SOF0-SOF15, excluding the DHT/JPG/DAC markers that share the range
      if (marker >= 0xc0 && marker <= 0xcf && marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc) {
        return { format: 'jpeg', height: buf.readUInt16BE(i + 5), width: buf.readUInt16BE(i + 7) };
      }
      i += 2 + buf.readUInt16BE(i + 2);
    }
    return { format: 'jpeg', width: 0, height: 0 };
  }
  if (buf[0] === 0x52 && buf[1] === 0x49 && buf[2] === 0x46 && buf[3] === 0x46) return { format: 'webp', width: 0, height: 0 };
  return null;
}

// A short, stable fingerprint for the record. The identical check itself is an
// exact buffer comparison, so this never has to carry that weight.
function fingerprint(buf) {
  let h = 0x811c9dc5;
  for (let i = 0; i < buf.length; i++) {
    h ^= buf[i];
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h.toString(16).padStart(8, '0') + '-' + buf.length;
}

const facts_available = before.kind === 'buffer' && after.kind === 'buffer';
let images_identical = false;
let beforeDim = null;
let afterDim = null;
let beforeFp = '';
let afterFp = '';
let sizeDeltaPct = 0;
const notes = [];

if (facts_available) {
  images_identical = before.buf.length === after.buf.length && before.buf.equals(after.buf);
  beforeDim = dimensions(before.buf);
  afterDim = dimensions(after.buf);
  beforeFp = fingerprint(before.buf);
  afterFp = fingerprint(after.buf);
  sizeDeltaPct = before.buf.length ? Math.round(((after.buf.length - before.buf.length) / before.buf.length) * 100) : 0;
  if (!beforeDim || !afterDim) notes.push('could not read dimensions from one of the files - is it really an image?');
} else {
  notes.push('images supplied as URLs, so the identical-file check and dimension facts are unavailable');
}

const canvasChanged = !!(beforeDim && afterDim && beforeDim.width && afterDim.width &&
  (beforeDim.width !== afterDim.width || beforeDim.height !== afterDim.height));
if (canvasChanged) {
  notes.push('the canvas size changed (' + beforeDim.width + 'x' + beforeDim.height + ' to ' +
    afterDim.width + 'x' + afterDim.height + '), so everything has moved and position-based findings should be read with care');
}

// --- the vision request -----------------------------------------------------
// Built here rather than in the HTTP node because it is a nested array of
// content parts, which is painful to express inline.
const dataUri = (img) => (img.kind === 'url' ? img.url : 'data:' + img.mime + ';base64,' + img.buf.toString('base64'));

const instructions = [
  'You are looking at two screenshots of the same interface: the FIRST is BEFORE, the SECOND is AFTER.',
  '',
  'Compare them carefully. Pay particular attention to the exact wording and capitalisation of',
  'every piece of text, and to colours - the changes that matter here are often small.',
  '',
  'Work through the image region by region - header, navigation, main content, controls,',
  'footer - and for each difference say where it is, what kind of change it is, and what it',
  'looked like before versus after.',
  '',
  'Rules:',
  '- Report only differences you can actually see. Do not speculate about causes.',
  '- Transcribe any text that changed exactly as it appears in each image.',
  '- If the two images look the same to you, say "NO VISIBLE DIFFERENCE" and stop. That is a',
  '  valid and useful answer, and inventing a difference is worse than finding none.',
  '- Do not describe things that are the same in both.',
  '- Be concise. Aim for well under 600 words: the output budget is small and a',
  '  truncated description is worse than a short one.',
  CONTEXT ? '' : null,
  CONTEXT ? 'What the tester said about this comparison: ' + CONTEXT : null,
].filter((l) => l !== null).join('\n');

return [{
  json: {
    issue_key: ISSUE_KEY,
    context: CONTEXT,
    facts_available,
    images_identical,
    before_dimensions: beforeDim,
    after_dimensions: afterDim,
    before_fingerprint: beforeFp,
    after_fingerprint: afterFp,
    before_bytes: before.kind === 'buffer' ? before.buf.length : 0,
    after_bytes: after.kind === 'buffer' ? after.buf.length : 0,
    size_delta_pct: sizeDeltaPct,
    canvas_changed: canvasChanged,
    inspection_notes: notes,

    // consumed by the HTTP node
    // qwen3.8 rather than the qwen3.6 that 01_Screenshot_To_Bug_Reporter uses.
    // Measured side by side on the same pair: 3.6 called two genuinely
    // different screenshots identical, while 3.8 found the changed button
    // label. 3.6 allows five images against 3.8's three, which is what decided
    // it for 01_ - but a comparison only ever needs two, and catching the
    // subtle case is the entire job here.
    model: 'qwen/qwen3.8-27b',
    temperature: 0.2,
    // Learned building 01_Screenshot_To_Bug_Reporter: qwen3.6 is a thinking
    // model, and left on it spends the whole completion budget reasoning and
    // returns a truncated answer.
    reasoning_effort: 'none',
    // Groq's vision tier caps OUTPUT tokens per minute at 1,000 and counts this
    // ceiling as requested rather than used, so 1,200 is rejected outright
    // before the model runs. 01_Screenshot_To_Bug_Reporter hit the same wall.
    max_completion_tokens: 800,
    messages: [{
      role: 'user',
      content: [
        { type: 'text', text: instructions },
        { type: 'image_url', image_url: { url: dataUri(before) } },
        { type: 'image_url', image_url: { url: dataUri(after) } },
      ],
    }],
  },
}];

