      "type": "string",
      "description": "One sentence a developer would understand read aloud in a standup."
    },
    "differences": {
      "type": "array",
      "description": "One entry per distinct change. Empty when nothing changed - that is a valid answer.",
      "items": {
        "type": "object",
        "required": [
          "region",
          "element",
          "change_type",
          "before_state",
          "after_state",
          "severity"
        ],
        "properties": {
          "region": {
            "type": "string",
            "description": "Where on the screen: header, the card, the form, controls, footer."
          },
          "element": {
            "type": "string",
            "description": "The specific thing that changed, named as the description names it."
          },
          "change_type": {
            "type": "string",
            "enum": [
              "Colour",
              "Spacing or Alignment",
              "Text or Wording",
              "Missing Element",
              "Added Element",
              "Size or Scale",
              "State or Styling",
              "Image or Icon",
              "Layout Reflow",
              "Unable to Determine"
            ]
          },
          "before_state": {
            "type": "string"
          },
          "after_state": {
            "type": "string"
          },
          "severity": {
            "type": "string",
            "enum": [
              "S0 - Blocker",
              "S1 - Critical",
              "S2 - Major",
              "S3 - Minor",
              "S4 - Trivial"
            ]
          }
        }
      }
    },
    "likely_cause": {
      "type": "string",
      "description": "Only when several changes point at the same cause, otherwise \"Unable to Determine\"."
    },
    "developer_note": {
      "type": "string",
      "description": "What to look at, written for whoever will fix it."
    },
    "questions": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "What a pair of screenshots cannot answer."
    },
    "confidence": {
      "type": "string",
      "enum": [
        "High",
        "Medium",
        "Low"
      ]
    }
  }
}

parameters.jsCode:
// Apply the guard rails and build the two message bodies.
//
// This node sits on both paths: the one where a vision call happened, and the
// short-circuit where the two files turned out to be byte-identical and no
// model was called at all. That second path is guard rail 1, and it is the
// reason the node reads the model output defensively rather than assuming it.

const facts = $('Inspect Images').first().json;

let model = {};
try {
  const incoming = $input.first().json;
  model = (incoming && incoming.output) || incoming || {};
} catch (e) { model = {}; }
if (typeof model !== 'object' || Array.isArray(model)) model = {};

const CHANGE_TYPES = ['Colour', 'Spacing or Alignment', 'Text or Wording', 'Missing Element',
  'Added Element', 'Size or Scale', 'State or Styling', 'Image or Icon', 'Layout Reflow', 'Unable to Determine'];
const SEVERITIES = ['S0 - Blocker', 'S1 - Critical', 'S2 - Major', 'S3 - Minor', 'S4 - Trivial'];
const VERDICTS = ['Difference Found', 'No Difference', 'Cannot Compare'];
const CONFIDENCES = ['High', 'Medium', 'Low'];

const notes = [];
const str = (v, fallback) => {
  if (v === undefined || v === null) return fallback;
  const s = String(v).trim();
  return s === '' ? fallback : s;
};
const oneOf = (v, allowed, fallback) => {
  const s = str(v, '');
  return allowed.find((a) => a.toLowerCase() === s.toLowerCase()) || fallback;
};
const arr = (v) => (Array.isArray(v) ? v : []);

// --- guard rail 2: every difference must be localised -----------------------
// "The layout feels different" is the absence of a defect report, not one.
let dropped = 0;
let differences = arr(model.differences)
  .map((d) => ({
    region: str(d && d.region, ''),
    element: str(d && d.element, ''),
    change_type: oneOf(d && d.change_type, CHANGE_TYPES, 'Unable to Determine'),
    before_state: str(d && d.before_state, ''),
    after_state: str(d && d.after_state, ''),
    severity: oneOf(d && d.severity, SEVERITIES, 'S4 - Trivial'),
  }))
  .filter((d) => {
    const located = d.region || d.element;
    const described = (d.before_state && d.after_state) || d.element;
    if (!located || !described) { dropped++; return false; }
    return true;
  });
if (dropped) notes.push(dropped + ' difference(s) dropped for naming no location or no before/after state');

let verdict = oneOf(model.verdict, VERDICTS, differences.length ? 'Difference Found' : 'No Difference');
let confidence = oneOf(model.confidence, CONFIDENCES, 'Low');
let summary = str(model.summary, '');
let developer_note = str(model.developer_note, 'Not Provided');

// --- guard rail 1: identical files cannot have differences ------------------
if (facts.images_identical) {
  if (differences.length) {
    notes.push('the two files are byte-identical, so ' + differences.length + ' reported difference(s) were discarded');
  }
  differences = [];
  verdict = 'No Difference';
  confidence = 'High';
  summary = 'The two screenshots are byte-identical. Nothing changed.';
  developer_note = 'No action needed. The before and after files are the same file.';
}

// --- guard rail 3: the canvas size is a fact --------------------------------
if (facts.canvas_changed) {
  const b = facts.before_dimensions || {};
  const a = facts.after_dimensions || {};
  notes.push('canvas changed from ' + b.width + 'x' + b.height + ' to ' + a.width + 'x' + a.height +
    ' - position findings may be capture artefacts');
  if (confidence === 'High') confidence = 'Medium';
}

if (!facts.facts_available) {
  notes.push('images were supplied as URLs, so the identical-file check did not run');
  if (confidence === 'High') confidence = 'Medium';
}

if (verdict === 'Difference Found' && !differences.length) {
  verdict = 'No Difference';
  notes.push('verdict said a difference was found but nothing survived validation');
}
if (!summary) {
  summary = verdict === 'No Difference' ? 'No visible difference between the two screenshots.'
    : differences.length + ' visual difference(s) found.';
}

const bySeverity = (s) => differences.filter((d) => d.severity.startsWith(s)).length;
const worst = SEVERITIES.find((s) => differences.some((d) => d.severity === s)) || 'None';

const report = {
  verdict,
  summary,
  confidence,
  differences,
  difference_count: differences.length,
  worst_severity: differences.length ? worst : 'None',
  change_types: Array.from(new Set(differences.map((d) => d.change_type))),
  likely_cause: str(model.likely_cause, 'Unable to Determine'),
  developer_note,
  questions: arr(model.questions).map((q) => String(q).trim()).filter(Boolean).slice(0, 5),

  // measured, never asked for
  images_identical: !!facts.images_identical,
  canvas_changed: !!facts.canvas_changed,
  before_dimensions: facts.before_dimensions,
  after_dimensions: facts.after_dimensions,
  size_delta_pct: facts.size_delta_pct,
  facts_available: !!facts.facts_available,
  issue_key: facts.issue_key || '',
  context: facts.context || '',
  differences_dropped: dropped,
  validation_notes: notes.length ? notes : ['No corrections were needed'],
};

// --- message bodies ---------------------------------------------------------
const dim = (d) => (d && d.width ? d.width + 'x' + d.height : 'unknown');
const lines = differences.map((d, i) =>
  (i + 1) + '. [' + d.severity + '] ' + d.change_type + ' - ' + (d.region || 'unspecified region') +
  (d.element ? ', ' + d.element : '') +
  (d.before_state && d.after_state ? '\n   before: ' + d.before_state + '\n   after:  ' + d.after_state : ''));

const body = [
  'Visual diff: ' + report.verdict,
  '',
  report.summary,
  '',
  report.difference_count ? 'Differences found:\n' + lines.join('\n') : 'No differences were found.',
  '',
  'Canvas: ' + dim(report.before_dimensions) + ' -> ' + dim(report.after_dimensions) +
    (report.canvas_changed ? '  (changed - position findings may be capture artefacts)' : '  (unchanged)'),
  'Confidence: ' + report.confidence + (report.likely_cause !== 'Unable to Determine' ? '   Likely cause: ' + report.likely_cause : ''),
  '',
  'For the developer: ' + report.developer_note,
  report.questions.length ? '\nOpen questions:\n' + report.questions.map((q) => '- ' + q).join('\n') : '',
  '',
  report.validation_notes[0] === 'No corrections were needed' ? '' : 'Notes: ' + report.validation_notes.join(' | '),
].filter((l) => l !== '').join('\n');

report.telegram_text = body;
report.jira_comment = body + '\n\nDrafted automatically from a before/after screenshot pair. ' +
  'Every figure above was measured from the image files; the description was reviewed against them.';

return [{ json: report }];
